-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[12986] = { id = 12986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Titans", description = "Norgannon's Core is not at this location. I am not sure why you seek it, {race}, and I am equally unsure if you truly know the purpose of that which you seek.\n\nI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.", progress = "Have you returned with the knowledge that I seek, {race}?", completion = "The news you bear forth is grave indeed. I do not know the fate of the remaining watchers, but their absence spells dark times for all of the lands of Azeroth.\n\nI shall examine the knowledge contained in the databank that you have returned and attempt to fully assess the situation. I believe I am in possession of knowledge that you deem more pertinent at this moment however, so I shall allow you to partake in said wisdom first.", objectives = "Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12987] = { id = 12987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing Hodir's Helm", description = "The helm is forged.\n\nYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.\n\nIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.\n\nFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.\n\nEnjoy the privilege, {class}. Never before has an outsider been given such an honor!", progress = "Have you placed Hodir's Helm, {race}?", completion = "<Njormeld gazes up at Hodir's Helm, visibly moved.>\n\nThat will do, little {race}.\n\nThat will do....", objectives = "Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12988] = { id = 12988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Forges!", description = "In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.\n\nNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, {name}, for it will mean the end of the refuge.\n\nGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.", completion = "Excellent work! Oh, it won't stop the iron dwarves, but it'll take them valuable time to rebuild those forges. I daresay we've gained the advantage.", objectives = "Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12989] = { id = 12989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slithering Darkness", description = "The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.\n\nAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.", completion = "The jormungar are vile creatures.  You did well in destroying them.", objectives = "Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12990] = { id = 12990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormhole", description = "Bring me materials and I'll teach you how to use your Wormhole Generator.You will learn:", objectives = "Bring Jon LeCraft the materials he seeks to avoid a swift death, and to get a cool new spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12991] = { id = 12991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Them Where it Hurts", description = "Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.\n\nNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.", completion = "There were days when I could never ask someone to do what you did, but my experience with the iron dwarves has extinguished those feelings. We have bought time against the enemy's advance.", objectives = "Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12992] = { id = 12992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Dem Vrykuls!", description = "Dem vrykuls at the Jotunheim needs to be crushed!\n\n{name} crush dems good!", completion = "{name} is my bestest little {race}!", objectives = "Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12993] = { id = 12993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Colossal Threat", description = "You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.\n\nEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.", progress = "Did you find the documents we're looking for?", completion = "<Bouldercrag begins to look over the documents, his eyes wide.>\n\nI had no idea the irons were capable of this! Our men will have no chance against this behemoth if it's completed. Fortunately, it looks like they're still lacking a key part.", objectives = "Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12994] = { id = 12994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Hunter", description = "The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.\n\nFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips--at least you think you do.\n\nIt would seem that she senses danger outside the stronghold and wants you to do something about it.\n\nWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...", progress = "The frostworg denmother looks at you curiously.", completion = "As you slide the chain back around the denmother's neck she licks your face approvingly.", objectives = "You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.\n\nUsing the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12995] = { id = 12995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Our Mark", description = "We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.\n\nI want you to demoralize them.\n\nMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.\n\nLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.", completion = "Well done, {name}. Let them see the desecrated corpses of their fallen comrades and think twice about striking at us!\n\nIf you come back tomorrow, I will make certain to have more banners prepared for you.", objectives = "Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12996] = { id = 12996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warm-Up", description = "You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.\n\nA good bear won't do you much good without the skill to ride it.\n\nI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.", progress = "How did it go with the yeti?", completion = "Not bad.  I was hoping Kirgaraak would snap your neck so I could keep your bear.\n\nJust joking, sister.  Well... half-joking.  That's a really nice bear you've got.", objectives = "Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12997] = { id = 12997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Pit", description = "Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.\n\nHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.\n\nGlory awaits, should you succeed.", completion = "You really did it!  You made it out with your health.  Wish we could say the same for your bear.\n\nIt's going to take a while for her to recover.  Fortunately you won't need her for a while.", objectives = "Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12998] = { id = 12998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Storm", description = "According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.\n\nWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!\n\nNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.", completion = "With the heart in the hands of Narvir, the colossus will achieve its full power! We'll have no choice but to fight it.", objectives = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12999] = { id = 12999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bone Witch", description = "You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.\n\nThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.\n\nShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.", completion = "{name}, you came.\n\nAlready I have heard of your activities on the Savage Ledge. This is good. I am glad that you seem willing to help with undermining the vrykul here at Jotunheim.\n\n\n\nYou and I are going to have a great deal of fun with them!", objectives = "Speak with The Bone Witch within the cave at Njorndar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13000] = { id = 13000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Measures", description = "The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.\n\nWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.\n\nWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.", progress = "Did you bring the furs?", completion = "These furs are rather... large.  I'd hate to see the worgs you had to face off with.\n\nWe're all very thankful.  The temperature is starting to drop already.", objectives = "Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13001] = { id = 13001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Hodir's Spear", description = "The time has come, little {class}. The stars have foretold of this day.\n\nI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.\n\nWe must obey! Were we to fail in receiving this gift, doom would surely follow.\n\nI call upon you to assist me in this sacred undertaking.\n\nGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.", progress = "Have you gathered the materials for the spear, {race}?", completion = "Stand back, {race}, and behold the fulfilling of a prophecy!", objectives = "Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13002] = { id = 13002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "Welcome to de cold, mon.  Dis place may not be so good for keepin' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin' is some gems to do me work on.\n\nBring me some gems and I be teachin' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin' an uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba'li in Warsong Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13003] = { id = 13003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How To Slay Your Dragon", description = "Hodir's Spear is an icon of great prowess in battle.\n\nIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.\n\nScanning the horizon, your vision locks on a wild wyrm as it flies nearby.\n\nIt is decided. Of you and he, only one shall see the next sunrise....", progress = "The wyrm cries out, almost as if mocking you. Will you accept the challenge?", completion = "It is done.\n\nYou have stared certain death in the face and emerged victorious.\n\nBy single-handedly defeating such a mighty beast, you have brought great honor to Dun Niffelem!", objectives = "You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13004] = { id = 13004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gem Perfection", description = "There's a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13005] = { id = 13005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earthen Oath", description = "For years I neglected my duties, giving into defeat and self-pity.\n\nNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.\n\nEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.\n\nThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.", completion = "It's a good start.  But my brother's forces will not take long to regroup.  We must make our victory a decisive one.", objectives = "Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13006] = { id = 13006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Viscous Cleaning", description = "As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.\n\nNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.\n\nJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.", progress = "Frost is thickening on the helm as you watch, and icicles are beginning to form around its edges...", completion = "As you coat the helm with a thin layer of oil, the frost falls away and the surface gleams.", objectives = "You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.\n\nYou are then to return to Dun Niffelem and apply the oil to Hodir's Helm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13007] = { id = 13007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Colossus", description = "We have failed to prevent the completion of the iron colossus, {name}, which means we have no choice but to face it in battle.\n\nBruor has devised a plan to exploit the colossus' only weakness.\n\nNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the iron colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.", completion = "We've done it, we've really done it! The refuge is spared and the stormforged are defeated! We must warn Brann before Loken gets it in his mind to try to rebuild his forces. The only way to secure the victory you have won today is to go into Ulduar and defeat Loken for all time!", objectives = "Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13008] = { id = 13008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge Tactics", description = "We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.\n\nFree our crusaders trapped on the field outside the base, {class}!", completion = "There are still many Argent Crusade soldiers out on that field and in Scourgeholme, {name}. While your help is appreciated, there is still much left to be done.", objectives = "Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 5 Webbed Crusaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13009] = { id = 13009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.\n\nMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.", progress = "How have your efforts fared, {class}?", completion = "<As you present Thorim with the reforged suit of armor, he is visibly stricken by its splendor.>\n\nYou have done well, {race}, but there remains much to be done.", objectives = "Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13010] = { id = 13010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krolmir, Hammer of Storms", description = "One task remains before I can reclaim my home at the Terrace of the Makers.\n\nKrolmir must be found.\n\nOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.\n\nI've thought it lost for these many years, but now I must be certain.\n\nReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.", progress = "Back again, little {race}?", completion = "Words cannot express my gratitude, {class}.\n\nYou have served me honorably. Please accept this token of my gratitude.", objectives = "Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13011] = { id = 13011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling Jorcuttar", description = "The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.\n\nThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.\n\nShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.", progress = "Have you slain Jormuttar?", completion = "So it is done.\n\nWe have heard the screams of Jormuttar as they echoed from across the valley.\n\nYou have done our people a service this day, little {race}.", objectives = "King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[13012] = { id = 13012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sardis the Elder", objectives = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
